var DX_BODY = window.DX_BODY || {};

/* ==================== مراحل الحمل ==================== */

DX_BODY['pregnancy-first-trimester'] = {
  symptoms: {
    ar: 'أول ما تلاحظه المرأة غياب الدورة، ثم تتوالى علامات هادئة تختلف من واحدة لأخرى: غثيان يأتي في الصباح أو طول اليوم، وحساسية شديدة للروائح، وتعب يغلبها فتنام في غير وقتها، وثقل وألم في الثديين، وكثرة تبوّل، وتقلّب مزاج ونفور من طعام كانت تحبّه واشتهاء لآخر. بعضهنّ لا تشعر بشيء يُذكر وهذا طبيعي أيضاً ولا يعني خطراً على الحمل. الغثيان مزعج لكنه غالباً علامة حمل سائر بخير، ويبلغ ذروته حول الأسبوع التاسع ثم يخفّ. وما يقلق هو أن يشتدّ حتى يمنع أيّ أكل أو شرب، أو أن يصحبه نزيف أو ألم بطن قويّ.',
    en: 'The first thing a woman notices is a missed period, then quiet signs follow that differ from one to another: nausea in the morning or all day, a strong sensitivity to smells, tiredness that overtakes her so she sleeps at odd times, heaviness and soreness of the breasts, frequent urination, mood swings, and going off a food she loved while craving another. Some feel almost nothing, and this too is normal and does not mean danger to the pregnancy. Nausea is unpleasant but is usually a sign of a pregnancy going well; it peaks around the ninth week then eases. What worries is that it becomes so severe it prevents any eating or drinking, or that it comes with bleeding or strong abdominal pain.'
  },
  cause: {
    ar: 'بعد التقاء البويضة بالحيوان المنوي تنغرس النطفة في جدار الرحم، وتبدأ من نقطة واحدة رحلةٌ مذهلة: في هذه الثلاثة عشر أسبوعاً تتشكّل أعضاء الجنين كلّها تقريباً — القلب الذي يبدأ نبضه باكراً، والدماغ والحبل الشوكي، والأطراف والوجه. لهذا يُسمّى الثلث الأول فصل التكوّن، وفيه يكون الجنين أكثر حساسية لما يصل إليه من دخان أو كحول أو أدوية أو عدوى. والأعراض التي تشعر بها الأمّ سببها ارتفاع سريع لهرمونات الحمل، وأهمّها الهرمون الذي تفرزه المشيمة الناشئة، وهو نفسه الذي يظهر في اختبار الحمل. هذه الهرمونات ترخي المعدة وتبطئ الهضم فيظهر الغثيان والحرقة، وتوسّع الأوعية فيظهر الدوار والتعب.',
    en: 'After the egg meets the sperm, the fertilised cell implants in the wall of the womb, and from a single point an astonishing journey begins: in these thirteen weeks almost all the baby organs take shape — the heart that starts beating early, the brain and spinal cord, the limbs and face. This is why the first trimester is called the forming stage, and in it the baby is most sensitive to what reaches it from smoke, alcohol, medicines or infection. The symptoms the mother feels come from a rapid rise in pregnancy hormones, chiefly the one the young placenta secretes, the same one that shows on a pregnancy test. These hormones relax the stomach and slow digestion so nausea and heartburn appear, and widen the vessels so dizziness and tiredness show.'
  },
  diagnosis: {
    ar: 'يُثبَت الحمل باختبار بول منزليّ يكفي غالباً، ويؤكّده تحليل دم إن لزم. الخطوة العملية الأهمّ حجز أول زيارة للمتابعة مبكّراً، إذ تُسجَّل فيها آخر دورة لتقدير الموعد، ويُقاس الضغط والوزن، ويُطلب فحص دم أساسي يشمل فصيلة الدم والعامل الريصي ومخزون الحديد والمناعة ضدّ بعض العدوى. ويُنصح بحمض الفوليك قبل الحمل وفي أشهره الأولى وقايةً لعمود الجنين الفقري، وطبيبك يحدّده. وبين الأسبوعين السادس والثالث عشر تُجرى موجات صوتية مبكّرة تؤكّد أن الحمل داخل الرحم وأنه واحد أو أكثر، وتضبط عمر الحمل بدقّة أكبر من الحساب باليوم، وهذا التاريخ المبكّر يبقى المرجع لبقيّة الحمل.',
    en: 'Pregnancy is confirmed by a home urine test that is usually enough, backed by a blood test if needed. The most important practical step is to book the first antenatal visit early, where the last period is recorded to estimate the date, blood pressure and weight are measured, and a basic blood panel is requested covering blood group and rhesus factor, iron stores and immunity to some infections. Folic acid is advised before pregnancy and in its early months to protect the baby spine, and your doctor decides it. Between the sixth and thirteenth weeks an early ultrasound confirms that the pregnancy is inside the womb and whether it is one or more, and sets the gestational age more precisely than counting by date; this early dating remains the reference for the rest of pregnancy.'
  },
  treatment: {
    ar: 'ليس فصلاً يُعالَج بل يُدار براحة وعناية. للغثيان يفيد الأكل القليل المتكرّر بدل الوجبات الكبيرة، وتجنّب الروائح المثيرة، وشرب الماء على مهل، والبدء بشيء خفيف قبل النهوض من الفراش. الراحة عند التعب ليست كسلاً بل حاجة حقيقية في هذا الفصل. ويُبتعَد عن التدخين والكحول تماماً، ولا يؤخذ أيّ دواء أو عشبة إلا بعد سؤال الطبيب لأن هذا فصل تكوّن الأعضاء. من الأخطاء الشائعة الإفراط في الأكل بحجّة «أكل لاثنين» فالحاجة لا تكاد تزيد في هذا الفصل، وإهمال الغثيان الشديد حتى يصل للجفاف، والخوف من ممارسة الحياة الطبيعية والحركة الخفيفة وهي مفيدة. الاطمئنان النفسي جزء من العناية، فالقلق في هذا الفصل شائع جداً.',
    en: 'It is not a stage to be treated but one to be managed with rest and care. For nausea, small frequent eating instead of large meals helps, as do avoiding provoking smells, sipping water slowly, and starting with something light before rising from bed. Rest when tired is not laziness but a real need in this trimester. Smoking and alcohol are avoided entirely, and no medicine or herb is taken without asking the doctor, because this is the organ-forming stage. Common mistakes are overeating on the excuse of eating for two, when the need barely rises in this trimester; ignoring severe nausea until it reaches dehydration; and fearing ordinary life and gentle movement, which are beneficial. Peace of mind is part of the care, since worry in this trimester is very common.'
  },
  seeDoctor: {
    ar: 'اطلبي الطوارئ فوراً إذا حدث نزيف مهبليّ غزير، أو ألم حادّ في أسفل البطن على جانب واحد مع دوار أو إغماء، فقد يكون حملاً خارج الرحم وهو حالة تهدّد الحياة. وكذلك إذا لم تستطيعي حبس أيّ طعام أو شراب أكثر من يوم مع قلّة بول وجفاف. وخذي موعداً قريباً إذا ظهرت حرقة بول وألم عند التبوّل، أو حمّى، أو نزول بقع دم خفيفة تريدين الاطمئنان عليها. ولا تنتظري ظهور شكوى لتبدئي المتابعة: احجزي أول زيارة بمجرّد تأكّد الحمل، وابدئي حمض الفوليك مبكّراً — بل قبل الحمل إن كنتِ تخطّطين له — فأهمّ ما يقي عمود الجنين يقع في أسابيع قد تسبق علمك بالحمل.',
    en: 'Seek emergency care at once if heavy vaginal bleeding occurs, or sharp lower abdominal pain on one side with dizziness or fainting, since this may be an ectopic pregnancy, a life-threatening condition. The same applies if you cannot keep down any food or drink for more than a day with reduced urine and dehydration. Make an early appointment if burning and pain on urination appear, or a fever, or light spotting you want reassurance about. Do not wait for a complaint to start follow-up: book the first visit as soon as pregnancy is confirmed, and start folic acid early — indeed before pregnancy if you are planning it — because the most important protection for the baby spine occurs in weeks that may precede your knowing you are pregnant.'
  },
  updated: '2026-09-24'
};

DX_BODY['pregnancy-second-trimester'] = {
  symptoms: {
    ar: 'يوصف هذا الفصل بأنه أجمل فصول الحمل: يخفّ الغثيان وتعود الطاقة والشهية، ويهدأ المزاج. يبدأ البطن يظهر بوضوح، وتُحسّ حركة الجنين لأول مرة بين الأسبوع السادس عشر والثاني والعشرين، خفيفة كالفقاعات أوّلاً ثم تتّضح. ومع نموّ الرحم تظهر آلام شدّ خفيفة على جانبي البطن، وقد يظهر خطّ داكن أسفل البطن وتصبّغ في الوجه، واحتقان الأنف ونزف اللثة عند تنظيف الأسنان لكثرة الدم في الجسم. وتكبر الثديان استعداداً للرضاعة. كلّها تغيّرات طبيعية. وما ينبغي الانتباه له هو الصداع الشديد المستمرّ، أو تورّم مفاجئ في الوجه واليدين، أو قلّة واضحة في حركة الجنين بعد أن صارت منتظمة.',
    en: 'This trimester is described as the loveliest of pregnancy: nausea eases, energy and appetite return, and mood settles. The bump begins to show clearly, and the baby movements are felt for the first time between the sixteenth and twenty-second weeks, light like bubbles at first then clearer. As the womb grows, mild stretching pains appear on the sides of the abdomen, a dark line may show low on the belly with facial pigmentation, and nasal congestion and gum bleeding on brushing appear from the extra blood in the body. The breasts enlarge in readiness for feeding. These are all natural changes. What should be noticed is a severe persistent headache, sudden swelling of the face and hands, or a clear reduction in the baby movement after it has become regular.'
  },
  cause: {
    ar: 'دخل الجنين طور النموّ والصقل بعد أن اكتمل بناء أعضائه في الفصل الأول: ينمو حجمه وطوله، وتتشكّل بصماته وحواجبه ورموشه، ويبدأ يبلع ويسمع الأصوات من حوله. المشيمة الآن ناضجة تتولّى تغذيته وتنفّسه، وقد استقرّت هرمونات الحمل بعد صعودها الحادّ فخفّ الغثيان. حركة الجنين التي تُحسّ ناتجة عن قوّة عضلاته وسعة المكان الذي يتحرّك فيه، وتزداد وضوحاً كلّما كبر. تصبّغات الجلد سببها هرمونات الحمل التي تنشّط خلايا الصبغة، وتزول غالباً بعد الولادة. واحتقان الأنف والدوالي والبواسير التي قد تظهر سببها زيادة حجم الدم واسترخاء الأوعية وضغط الرحم المتنامي على أوردة الحوض.',
    en: 'The baby has entered the growing and refining phase after its organs were built in the first trimester: it grows in size and length, its fingerprints, eyebrows and eyelashes form, and it begins to swallow and to hear the sounds around it. The placenta is now mature, taking over its feeding and breathing, and pregnancy hormones have settled after their sharp rise so nausea has eased. The baby movement that is felt comes from the strength of its muscles and the room it has to move, growing clearer as it grows. Skin pigmentation comes from pregnancy hormones that activate the pigment cells and usually fades after birth. Nasal congestion, varicose veins and piles that may appear come from the increased blood volume, relaxed vessels and the growing womb pressing on the pelvic veins.'
  },
  diagnosis: {
    ar: 'هذا فصل الفحوص المطمئنة. حوالي الأسبوع العشرين يُجرى فحص التشريح بالموجات الصوتية، وهو مسح دقيق يتفحّص أعضاء الجنين عضواً عضواً — الدماغ والقلب والعمود والكليتين والأطراف — ويقيس نموّه ويطمئنّ على موضع المشيمة وكمية السائل، وفيه يُعرف الجنس غالباً إن رغب الأبوان. تُقاس في كلّ زيارة ضغط الأمّ ووزنها ويُفحص البول بحثاً عن بروتين أو سكّر. ويُعرض بين الأسبوعين الرابع والعشرين والثامن والعشرين فحص سكّري الحمل بشرب محلول سكّريّ وقياس السكّر بعده، خاصة لمن لديها عوامل خطر. وقد يُعاد فحص مخزون الحديد لأن الحمل يستهلكه. هذه الفحوص روتينية هدفها كشف ما لا تشعر به الأمّ مبكّراً.',
    en: 'This is the trimester of reassuring tests. Around the twentieth week the anatomy scan is done, a careful ultrasound that examines the baby organs one by one — brain, heart, spine, kidneys and limbs — measures its growth, and checks the position of the placenta and the amount of fluid; the sex is usually known here if the parents wish. At every visit the mother blood pressure and weight are measured and the urine is checked for protein or sugar. Between the twenty-fourth and twenty-eighth weeks a gestational diabetes test is offered by drinking a sugary solution and measuring sugar afterwards, especially for those with risk factors. Iron stores may be rechecked because pregnancy uses them up. These tests are routine, aimed at detecting early what the mother cannot feel.'
  },
  treatment: {
    ar: 'فصل يُستثمر لا يُعالَج. الطاقة العائدة فرصة لحركة منتظمة معتدلة كالمشي والسباحة، فهي تخفّف آلام الظهر وتحسّن النوم وتهيّئ الجسم للولادة. يُنصح بالنوم على الجنب مع تقدّم البطن، وبمرطّب للجلد الممتدّ، وبعناية باللثة والأسنان لأن الحمل يزيد التهابها. الغذاء المتنوّع مع مصدر جيّد للحديد والكالسيوم يكفي حاجة النموّ. من الأخطاء الشائعة إهمال ألم الظهر حتى يشتدّ بدل تقويته بالحركة مبكّراً، والاعتقاد أن التصبّغات تحتاج علاجاً وهي تزول تلقائياً، وتفويت فحص التشريح أو فحص السكّري ظنّاً أن الحمل يمرّ بخير. هذا وقت مناسب أيضاً للتحضير النفسي وحضور دروس الولادة إن توفّرت.',
    en: 'A trimester to invest, not to treat. The returning energy is a chance for regular moderate activity such as walking and swimming, which eases back pain, improves sleep and prepares the body for birth. Sleeping on the side is advised as the belly grows, along with a moisturiser for the stretching skin and care of the gums and teeth, since pregnancy increases their inflammation. Varied food with a good source of iron and calcium meets the needs of growth. Common mistakes are ignoring back pain until it worsens rather than strengthening early with movement, believing pigmentation needs treatment when it fades on its own, and skipping the anatomy scan or the diabetes test on the assumption that all is well. This is also a good time for mental preparation and attending birth classes if available.'
  },
  seeDoctor: {
    ar: 'اطلبي الطوارئ فوراً إذا حدث نزيف مهبليّ، أو تدفّق ماء من المهبل قبل الأسبوع السابع والثلاثين، أو انقباضات منتظمة مؤلمة تتكرّر قبل موعدها، فقد تكون ولادة مبكّرة. وكذلك عند صداع شديد لا يزول مع اضطراب رؤية أو ألم أعلى البطن أو تورّم مفاجئ في الوجه واليدين، فهذه علامات ارتفاع ضغط الحمل. وخذي موعداً قريباً إذا شعرت بحرقة بول أو حمّى، أو لاحظت أن حركة الجنين صارت أقلّ بوضوح بعد أن انتظمت. أمّا آلام الشدّ الجانبية الخفيفة وتصلّب البطن العابر فطبيعية ولا تستدعي قلقاً ما لم تصر منتظمة ومؤلمة. ولا تفوّتي فحص التشريح حول الأسبوع العشرين ولو كنتِ بخير.',
    en: 'Seek emergency care at once if vaginal bleeding occurs, or a gush of water from the vagina before the thirty-seventh week, or regular painful contractions recurring before their time, since this may be preterm labour. The same applies to a severe headache that does not lift with visual disturbance, upper abdominal pain, or sudden swelling of the face and hands, which are signs of raised pregnancy blood pressure. Make an early appointment if you feel burning on urination or fever, or notice the baby movement has clearly lessened after becoming regular. Mild side stretching pains and passing tightening of the belly are natural and need no worry unless they become regular and painful. And do not miss the anatomy scan around the twentieth week even if you are well.'
  },
  updated: '2026-09-24'
};

DX_BODY['pregnancy-third-trimester'] = {
  symptoms: {
    ar: 'يثقل الجسم مع كبر الجنين، فتظهر شكاوى الحمل الأواخر: ضيق نفس لأن الرحم يضغط الحجاب الحاجز، وحرقة معدة، وكثرة تبوّل مجدّداً لضغط الرأس على المثانة، وألم أسفل الظهر والحوض، وتورّم القدمين والكاحلين آخر النهار، وأرق وصعوبة إيجاد وضعية نوم. تشتدّ حركة الجنين ثم تتغيّر طبيعتها في الأسابيع الأخيرة إذ يضيق مكانه فتصير تمطّطاً ودحرجة أكثر من ركل. وتظهر انقباضات تجريبية غير منتظمة وغير مؤلمة تشدّ البطن ثوانيَ ثم ترتخي، وهي بروفة لا ولادة. وقرب الموعد قد ينزل الجنين للحوض فيخفّ ضيق النفس ويزيد ضغط الحوض. كلّها علامات اقتراب لا خطر.',
    en: 'The body grows heavy as the baby grows, so the complaints of late pregnancy appear: breathlessness as the womb presses the diaphragm, heartburn, frequent urination again as the head presses the bladder, low back and pelvic pain, swelling of the feet and ankles by evening, and poor sleep with difficulty finding a position. The baby movement grows stronger then changes in character in the last weeks, as its space narrows, becoming more stretching and rolling than kicking. Practice contractions appear, irregular and painless, tightening the belly for seconds then relaxing, a rehearsal not a birth. Near the date the baby may drop into the pelvis so breathlessness eases and pelvic pressure rises. These are all signs of approach, not danger.'
  },
  cause: {
    ar: 'الجنين في هذا الفصل يكسب أغلب وزنه، وتنضج رئتاه أخيراً استعداداً لأول نفَس، ويتراكم تحت جلده دهن يدفّئه بعد الولادة، وينزل رأسه غالباً إلى أسفل استعداداً للمخرج. حجمه المتنامي هو سبب أغلب أعراض الأمّ: يزاحم المعدة فيرفع الحمض ويسبّب الحرقة، ويرفع الحجاب الحاجز فيضيق النفس، ويثقل على أوردة الحوض والساقين فيحبس السوائل ويورّم القدمين. هرمونات الحمل ترخي أربطة الحوض تمهيداً للولادة فيظهر ألمه، وتبطئ الأمعاء فيزيد الإمساك. الانقباضات التجريبية تمرين لعضلة الرحم على الشدّ، والقلق وصعوبة النوم طبيعيان مع اقتراب حدث كبير وثقل الجسم.',
    en: 'In this trimester the baby gains most of its weight, its lungs finally mature ready for the first breath, fat gathers under its skin to keep it warm after birth, and its head usually turns downward ready for the exit. Its growing size causes most of the mother symptoms: it crowds the stomach so acid rises and heartburn appears, lifts the diaphragm so breath narrows, and weighs on the pelvic and leg veins so fluid is held and the feet swell. Pregnancy hormones relax the pelvic ligaments in preparation for birth so their pain appears, and slow the bowel so constipation increases. The practice contractions are the womb muscle exercising its squeeze, and anxiety and poor sleep are natural as a great event nears and the body grows heavy.'
  },
  diagnosis: {
    ar: 'تصبح زيارات المتابعة أقرب: كلّ أسبوعين ثم كلّ أسبوع قرب الموعد. في كلّ زيارة يُقاس الضغط والوزن، ويُفحص البول للبروتين، ويُقاس ارتفاع الرحم لتقدير نموّ الجنين، ويُلمس البطن لمعرفة وضعية الجنين هل رأسه للأسفل، ويُسمع نبضه. تُطلب أحياناً موجات صوتية إضافية لتقدير الوزن والسائل وموضع المشيمة إن كان هناك داعٍ. ويُتابَع مخزون الحديد ويُعطى تطعيم يقي المولود بعض العدوى في أشهره الأولى حسب الدليل المحلي. تُشرح للأمّ علامات بدء المخاض ومتى تتوجّه للمستشفى، ويُوضع خطّة للولادة. الهدف من كثافة المتابعة كشف أيّ تغيّر في ضغط الأمّ أو نموّ الجنين مبكّراً حين يكون التصرّف أسهل.',
    en: 'Follow-up visits become closer: every two weeks, then weekly near the date. At each visit blood pressure and weight are measured, urine is checked for protein, the height of the womb is measured to estimate the baby growth, the belly is felt to learn the baby position and whether the head is down, and the heartbeat is heard. Extra ultrasounds are sometimes requested to estimate weight, fluid and placental position if there is a reason. Iron stores are followed and a vaccine is given to protect the newborn from some infections in its early months per the local guide. The mother is taught the signs that labour has begun and when to head to hospital, and a birth plan is made. The aim of the closer follow-up is to catch any change in the mother pressure or the baby growth early, when acting is easier.'
  },
  treatment: {
    ar: 'الإدارة راحةٌ وتحضير. لضيق النفس والحرقة يفيد الجلوس منتصباً بعد الأكل ووجبات أصغر وأكثر، ورفع الرأس عند النوم. للتورّم يُرفَع القدمان عند الجلوس ويُقلَّل الوقوف الطويل. لألم الظهر تمارين لطيفة ووضعية نوم على الجنب الأيسر مع وسادة بين الركبتين. تُشجَّع الحركة الخفيفة حتى قرب الموعد فهي تعين على الولادة. من الأخطاء الشائعة لزوم الفراش تماماً ظنّاً أنه أأمن، وإهمال قلّة حركة الجنين انتظاراً لتعود، وتفويت الزيارات المتقاربة لأنها كثيرة. هذا وقت تجهيز حقيبة المستشفى ومعرفة الطريق، والاطمئنان أن الانقباضات التجريبية والنزول للحوض علامات طبيعية لاقتراب موعد سعيد لا لخطر.',
    en: 'Management is rest and preparation. For breathlessness and heartburn, sitting upright after eating, smaller more frequent meals, and raising the head at night help. For swelling, the feet are raised when sitting and long standing reduced. For back pain, gentle exercises and sleeping on the left side with a pillow between the knees. Light activity is encouraged until near the date, since it aids birth. Common mistakes are taking to bed entirely thinking it safer, ignoring reduced baby movement while waiting for it to return, and skipping the closer visits because they are many. This is the time to prepare the hospital bag and know the route, and to be reassured that practice contractions and dropping into the pelvis are natural signs of a happy date approaching, not of danger.'
  },
  seeDoctor: {
    ar: 'اذهبي إلى المستشفى فوراً إذا نزفتِ، أو نزل ماء غزير، أو جاءتك انقباضات منتظمة مؤلمة كلّ خمس دقائق تشتدّ، أو قلّت حركة الجنين أو توقّفت — لا تنتظري إلى الصباح. واطلبي الطوارئ عند صداع شديد مع اضطراب رؤية أو ألم أعلى البطن أو تورّم مفاجئ، فهذه علامات ارتفاع ضغط الحمل الذي قد ينقلب سريعاً. وكذلك عند حمّى أو قشعريرة، أو ألم بطن حادّ مستمرّ. وخذي موعداً قريباً إذا زاد التورّم كثيراً أو ظهرت حكّة شديدة في الكفّين والقدمين خاصة ليلاً. أمّا الانقباضات التجريبية غير المنتظمة التي تزول بالراحة وتغيير الوضعية فطبيعية. وإن تجاوزتِ الأسبوع الأربعين فتُتابَعين عن قرب ولا تُترك الأمور بلا تقييم.',
    en: 'Go to hospital at once if you bleed, if a large amount of water passes, if regular painful contractions come every five minutes and intensify, or if the baby movement lessens or stops — do not wait until morning. Seek emergency care for a severe headache with visual disturbance, upper abdominal pain, or sudden swelling, since these are signs of raised pregnancy blood pressure that can turn quickly. The same applies to fever or chills, or persistent sharp abdominal pain. Make an early appointment if swelling increases greatly or intense itching appears on the palms and soles, especially at night. Irregular practice contractions that ease with rest and a change of position are natural. And if you pass the fortieth week you are followed closely and matters are not left without assessment.'
  },
  updated: '2026-09-24'
};

/* ==================== حساب وموعد ==================== */

DX_BODY['due-date'] = {
  symptoms: {
    ar: 'ما يشغل الأمّ هنا سؤالان: كم عمر حملي الآن، ومتى ألد؟ ويحيّرها أن الحساب يبدأ من أول يوم في آخر دورة لا من يوم حدوث الحمل، فيبدو الحمل «أسبوعين أكبر» ممّا تتوقّع. تسمع رقم أربعين أسبوعاً فتظنّه موعداً ثابتاً، ثم يمرّ فتقلق، مع أن الولادة قد تأتي طبيعياً قبله بأسابيع أو بعده بأيام. وقد تختلف الحسبة إذا كانت دورتها غير منتظمة أو لا تذكر تاريخ آخر دورة. فهم كيف يُحسب الحمل يريحها كثيراً: يجعلها تعرف في أيّ فصل هي، ومتى تُتوقَّع الفحوص، ومتى يصبح الجنين مكتملاً ينتظر خروجه في أيّ لحظة.',
    en: 'What occupies a mother here are two questions: how far along am I now, and when will I give birth? It puzzles her that counting starts from the first day of the last period, not the day pregnancy happened, so the pregnancy seems two weeks larger than she expects. She hears the number forty weeks and takes it as a fixed appointment, then it passes and she worries, although birth may come naturally weeks before it or days after. The count may differ if her cycle is irregular or she does not remember the date of her last period. Understanding how pregnancy is counted reassures her greatly: it lets her know which trimester she is in, when tests are expected, and when the baby becomes fully grown, awaiting its exit at any moment.'
  },
  cause: {
    ar: 'يُحسب الحمل من أول يوم في آخر دورة شهرية لأنه تاريخ تعرفه المرأة غالباً بدقّة، بينما يوم الإخصاب نفسه لا يُعرف تماماً. وبهذه الطريقة يكون متوسّط الحمل نحو أربعين أسبوعاً، أي عشرة أشهر قمرية لا تسعة كما يُقال. الإخصاب يقع فعلاً بعد أسبوعين تقريباً من بدء العدّ، عند التبويض في منتصف الدورة، لذلك يكون الجنين أصغر بأسبوعين من رقم أسابيع الحمل. الموعد المحسوب تقدير إحصائيّ لمنتصف نافذة الولادة الطبيعية، ولا يلده إلا قليل من النساء في يومه بالضبط. أمّا الولادة الطبيعية فتقع في أيّ وقت بين نهاية الأسبوع السابع والثلاثين وبداية الثاني والأربعين، وكلّها ضمن المدى السليم.',
    en: 'Pregnancy is counted from the first day of the last period because it is a date a woman usually knows precisely, whereas the day of fertilisation itself is not exactly known. By this method the average pregnancy is about forty weeks, that is ten lunar months, not nine as is said. Fertilisation actually occurs about two weeks after counting begins, at ovulation in mid-cycle, so the baby is two weeks smaller than the number of pregnancy weeks. The calculated date is a statistical estimate of the middle of the normal birth window, and few women deliver on it exactly. Natural birth occurs any time between the end of the thirty-seventh week and the start of the forty-second, all within the sound range.'
  },
  diagnosis: {
    ar: 'يُقدَّر الموعد أولاً بالحساب من آخر دورة، ثم يُضبط بالموجات الصوتية المبكّرة في الفصل الأول، وهي أدقّ وسيلة لتحديد عمر الحمل لأن كلّ الأجنّة تنمو بمعدّل متقارب في تلك الأسابيع. إذا اختلف تاريخ الموجات عن حساب الدورة بأيام كثيرة، يُعتمَد تاريخ الموجات لأنه أوثق، ويبقى هو المرجع لبقيّة الحمل ولا يُغيَّر لاحقاً. عملياً: احفظي تاريخ أول يوم في آخر دورة وأخبري به الطبيب في أول زيارة، واحرصي على موجات الفصل الأول لأنها تثبّت التاريخ. القياسات المتأخّرة في الفصل الثالث تقدّر الوزن لا العمر، لأن نموّ الأجنّة يتباعد آخر الحمل فلا يصلح لتأريخه. الموعد الموثَّق يوجّه توقيت كلّ الفحوص وقرار الولادة إن تأخّرت.',
    en: 'The date is first estimated by counting from the last period, then set by early ultrasound in the first trimester, the most accurate way to determine gestational age because all babies grow at a similar rate in those weeks. If the ultrasound date differs from the period count by many days, the ultrasound date is taken as more reliable, and it remains the reference for the rest of pregnancy and is not changed later. Practically: keep the date of the first day of your last period and tell the doctor at the first visit, and be sure to have the first-trimester scan because it fixes the date. Late measurements in the third trimester estimate weight, not age, because babies growth diverges near the end so it cannot date the pregnancy. The documented date guides the timing of all tests and the decision on birth if it is late.'
  },
  treatment: {
    ar: 'لا يُعالَج الموعد بل يُفهَم ويُستعمل. اعتبري الموعد نافذة لا يوماً، وخطّطي لجاهزية حقيبة المستشفى قبله بأسابيع لأن الولادة قد تسبقه. من الأخطاء الشائعة انتظار «اليوم المحدّد» بقلق يومي، والاعتقاد أن تجاوزه بيوم يعني خطراً، أو محاولة تعجيل الولادة بوصفات شعبية بلا داعٍ طبّي. عند تجاوز الأسبوع الأربعين تُكثَّف المتابعة لمراقبة الجنين والسائل، وقد يُقترَح تحفيز الولادة إذا اقترب الحمل من الأسبوع الثاني والأربعين، وهذا قرار طبّي يوازن بين نضج الجنين وسلامة استمرار الحمل. المهمّ أن المرأة تعرف رقم أسبوعها في كلّ لحظة، فهو مفتاح فهم أيّ نصيحة أو فحص يُطلب منها.',
    en: 'The date is not treated but understood and used. Regard it as a window, not a day, and plan the hospital bag ready weeks before it because birth may come first. Common mistakes are awaiting the exact day with daily anxiety, believing that passing it by a day means danger, or trying to hasten birth with folk remedies without medical need. Beyond the fortieth week, follow-up is intensified to watch the baby and the fluid, and inducing labour may be suggested as the pregnancy approaches the forty-second week, a medical decision balancing the baby maturity against the safety of continuing. What matters is that the woman knows her week number at every moment, since it is the key to understanding any advice or test asked of her.'
  },
  seeDoctor: {
    ar: 'خذي موعداً مبكّراً في الفصل الأول لتثبيت تاريخ الحمل بالموجات الصوتية، فهذا أهمّ ما يضبط بقيّة المتابعة. وراجعي إذا كنتِ لا تعرفين تاريخ آخر دورة أو كانت دوراتك غير منتظمة، فيُعتمد التقدير بالموجات وحدها. عند بلوغ الموعد وتجاوزه: راجعي حسب ما رتّبه طبيبك، ولا تتجاهلي مواعيد ما بعد الأربعين لأنها لمراقبة سلامة الجنين. واطلبي الطوارئ في أيّ أسبوع إذا بدأت علامات مخاض حقيقية — انقباضات منتظمة مؤلمة أو نزول ماء — أو إذا قلّت حركة الجنين. تذكّري أن الولادة قبل الأسبوع السابع والثلاثين تُعدّ مبكّرة وتحتاج تقييماً فورياً، وأن ما بين السابع والثلاثين والثاني والأربعين هو المدى الطبيعي.',
    en: 'Take an early appointment in the first trimester to fix the pregnancy date by ultrasound, as this is the most important thing that sets the rest of follow-up. See a doctor if you do not know the date of your last period or your cycles were irregular, so the estimate rests on ultrasound alone. On reaching and passing the date, attend as your doctor has arranged, and do not ignore the after-forty appointments, since they watch the baby wellbeing. Seek emergency care in any week if true labour signs begin — regular painful contractions or waters breaking — or if the baby movement lessens. Remember that birth before the thirty-seventh week is considered early and needs immediate assessment, and that between the thirty-seventh and forty-second weeks is the normal range.'
  },
  updated: '2026-09-24'
};

DX_BODY['fetal-movement'] = {
  symptoms: {
    ar: 'تحسّ الأمّ حركة جنينها أول مرة بين الأسبوع السادس عشر والثاني والعشرين، وتتأخّر قليلاً في الحمل الأول وعند من مشيمتها أمامية. تبدأ خفيفة كفقاعات أو رفرفة يصعب تمييزها، ثم تقوى وتصير ركلاً ودحرجة واضحة مع أواخر الفصل الثاني. لكلّ جنين ساعاته النشطة، وكثيراً ما ينشط حين تستريح أمّه أو بعد أكلها أو شربها شيئاً بارداً. في الأسابيع الأخيرة لا تقلّ الحركة بل تتغيّر طبيعتها إذ يضيق مكانه فتصير تمطّطاً وضغطاً أكثر من ركل. ما يستوجب الانتباه ليس نوع الحركة بل نقصها الواضح عن معتادها أو غيابها؛ إحساس الأمّ بنمط طفلها هو المقياس، لا رقم ثابت يصلح للجميع.',
    en: 'A mother feels her baby move for the first time between the sixteenth and twenty-second weeks, a little later in a first pregnancy and when the placenta is at the front. It starts light like bubbles or a flutter hard to distinguish, then strengthens into clear kicking and rolling by the end of the second trimester. Every baby has its active hours, and often becomes lively when its mother rests, or after she eats or drinks something cold. In the last weeks movement does not lessen but changes in nature, as its space narrows, becoming more stretching and pressing than kicking. What calls for attention is not the kind of movement but a clear reduction from its usual, or its absence; the mother sense of her baby pattern is the measure, not a fixed number that suits everyone.'
  },
  cause: {
    ar: 'حركة الجنين نتيجة نموّ جهازه العصبي وعضلاته: يتمرّن على ثني أطرافه والتقلّب والبلع، حتى قبل أن تشعر أمّه به. كلّما نضج الجهاز العصبي انتظم للجنين إيقاع نشاط ونوم يتكرّر خلال اليوم، لذلك تتعرّف الأمّ على أوقاته المعتادة. الحركة علامة اطمئنان لأنها تعكس أن الجنين يتلقّى أكسجيناً وغذاءً كافيين عبر المشيمة. وحين ينقص وصول الأكسجين لأيّ سبب، يوفّر الجنين طاقته فيقلّ نشاطه، ولهذا يكون نقص الحركة أحياناً أول إشارة يرسلها قبل أن يتغيّر أيّ فحص آخر. عوامل تُخفّف الإحساس بالحركة دون أن تعني خطراً: مشيمة أمامية تبطّن الضربات، انشغال الأمّ وحركتها التي تلهيها، ونوم الجنين الذي قد يمتدّ نحو ساعة.',
    en: 'Fetal movement results from the growth of its nervous system and muscles: it practises bending its limbs, turning and swallowing, even before its mother feels it. As the nervous system matures the baby settles into a repeating rhythm of activity and sleep through the day, so the mother learns its usual times. Movement is a reassuring sign because it reflects that the baby is receiving enough oxygen and food through the placenta. When oxygen delivery falls for any reason, the baby conserves its energy so its activity lessens, which is why reduced movement is sometimes the first signal it sends before any other test changes. Factors that dampen the sense of movement without meaning danger: a front-lying placenta that cushions the kicks, the mother being busy and moving so she is distracted, and the baby sleep, which may last about an hour.'
  },
  diagnosis: {
    ar: 'لا يُطلب عدّ محدّد من كلّ حامل، بل يُطلب أن تعرف الأمّ نمط طفلها المعتاد وتنتبه لأيّ تراجع واضح. إن شعرت بقلّة الحركة فالخطوة العملية: أن تتوقّف عمّا تفعل، وتشرب شيئاً وتستلقي على جنبها الأيسر في مكان هادئ، وتركّز على إحساس حركات طفلها. إن عادت الحركة لمعتادها اطمأنّت، وإن بقيت أقلّ راجعت دون تأخير ولو ليلاً. في العيادة يُسمَع نبض الجنين ويُسجَّل نمطه على جهاز خاص يقيس تسارعه مع الحركة، وقد تُجرى موجات صوتية لتقدير السائل ونشاط الجنين ووظيفة المشيمة. هذه فحوص سريعة غير مؤلمة هدفها التأكّد أن الجنين بخير، وطمأنة الأمّ جزء أساسي منها.',
    en: 'A specific count is not asked of every mother; rather she is asked to know her baby usual pattern and to notice any clear decline. If she feels reduced movement, the practical step is to stop what she is doing, drink something and lie on her left side in a quiet place, and focus on feeling her baby movements. If movement returns to usual she is reassured, and if it stays less she seeks review without delay, even at night. In the clinic the baby heartbeat is heard and its pattern recorded on a device that measures its acceleration with movement, and an ultrasound may estimate the fluid, the baby activity and the placenta function. These are quick painless tests aimed at confirming the baby is well, and reassuring the mother is an essential part of them.'
  },
  treatment: {
    ar: 'لا حركةَ تُعالَج، بل عادةٌ تُبنى: أن تنتبه الأمّ من الفصل الثالث لنمط طفلها اليومي. لا حاجة لعدّ ساعات بقلق، لكن أيّ إحساس بتراجع واضح يُختبَر فوراً بالراحة والتركيز كما سبق. من الأخطاء الشائعة والخطيرة تأجيل مراجعة نقص الحركة إلى الصباح أو إلى الموعد القادم، أو محاولة إيقاظ الجنين بمشروبات محلّاة أو بالوخز ثم الاكتفاء بذلك، أو الاطمئنان الكاذب بأنّ «الجنين ينام». القاعدة الذهبية: نقص الحركة تُراجَع لا تُنتظَر. وفي المقابل، لا تُقارن الأمّ حركة جنينها بحمل سابق أو بحوامل أخريات، فلكلّ جنين إيقاعه؛ المرجع هو معتاد هذا الطفل نفسه. إحساس الأمّ بأنّ «شيئاً تغيّر» يُؤخذ على محمل الجدّ دائماً.',
    en: 'No movement is treated; rather a habit is built: that the mother, from the third trimester, notices her baby daily pattern. There is no need to count hours anxiously, but any sense of a clear decline is tested at once by rest and focus as above. Common and dangerous mistakes are delaying review of reduced movement to the morning or the next appointment, trying to wake the baby with sweet drinks or prodding and then leaving it at that, or the false reassurance that the baby is sleeping. The golden rule: reduced movement is reviewed, not awaited. In turn, a mother should not compare her baby movement with a previous pregnancy or with other mothers, for every baby has its rhythm; the reference is this baby own usual. A mother sense that something has changed is always taken seriously.'
  },
  seeDoctor: {
    ar: 'راجعي دون تأخير — ولو كان الوقت ليلاً — إذا شعرت أن حركة جنينك أقلّ من معتادها أو توقّفت، ولم تعد بعد راحتك واستلقائك على جنبك الأيسر وتركيزك عليها مدّة. لا تنتظري إلى الصباح ولا إلى الموعد التالي؛ فحص سريع في المستشفى يطمئنك غالباً، والتأخير هو الخطر. اطلبي الطوارئ فوراً إذا صاحب قلّة الحركة نزيف أو ألم بطن أو نزول ماء. أمّا تغيّر نوع الحركة في الأسابيع الأخيرة إلى تمطّط ودحرجة مع بقاء إحساسك بها فطبيعيّ. وإذا تكرّر قلقك من الحركة أكثر من مرّة فأخبري طبيبك ليقرّر متابعة أقرب؛ تكرار الشعور بالتراجع علامة تستحقّ تقييماً أوسع لا مجرّد طمأنة عابرة.',
    en: 'Seek review without delay — even at night — if you feel your baby movement is less than usual or has stopped, and it has not returned after you rest, lie on your left side and focus on it for a while. Do not wait until morning or the next appointment; a quick hospital check usually reassures you, and delay is the danger. Seek emergency care at once if reduced movement comes with bleeding, abdominal pain or waters breaking. A change in the kind of movement in the last weeks to stretching and rolling, while you still feel it, is natural. And if your worry about movement recurs more than once, tell your doctor to arrange closer follow-up; a repeated sense of decline deserves wider assessment, not a passing reassurance alone.'
  },
  updated: '2026-09-24'
};

/* ==================== تغذية وسلامة ==================== */

DX_BODY['pregnancy-nutrition'] = {
  symptoms: {
    ar: 'تحتار الحامل بين نصائح متضاربة: قيل لها «كلي لاثنين»، وقيل لها امتنعي عن كلّ شيء تقريباً، فتقع بين إفراط وحرمان. عملياً ما تلاحظه: شهية متغيّرة تشتهي أطعمة وتنفر من أخرى، وغثيان يصعّب الأكل في الفصل الأول، وحرقة وإمساك مع تقدّم الحمل، ورغبة قوية في مأكولات معيّنة. بعضهنّ تخاف من زيادة الوزن، وأخرى لا تبالي. الحقيقة المطمئنة أنّ الحمل لا يتطلّب أكلاً مضاعفاً بل غذاءً أفضل نوعاً، وأن الزيادة الصحّية في الوزن معتدلة ومتدرّجة وتختلف حسب وزن الأمّ قبل الحمل. المطلوب ليس حمية قاسية ولا إفراطاً، بل توازناً تشعر معه الأمّ بالشبع والطاقة دون ثقل.',
    en: 'A pregnant woman is torn between conflicting advice: she is told to eat for two, and told to avoid almost everything, so she falls between excess and deprivation. Practically what she notices: a changing appetite craving some foods and rejecting others, nausea that makes eating hard in the first trimester, heartburn and constipation as pregnancy advances, and a strong desire for certain foods. Some fear weight gain, others do not mind. The reassuring truth is that pregnancy does not demand double the food but better quality food, and that healthy weight gain is moderate, gradual, and varies with the mother weight before pregnancy. What is required is neither a harsh diet nor excess, but a balance in which the mother feels full and energetic without heaviness.'
  },
  cause: {
    ar: 'يبني الجنين جسمه كلّه من غذاء أمّه عبر المشيمة، فتزداد حاجتها لبعض العناصر أكثر من حاجتها لمزيد من السعرات. حمض الفوليك يقي عمود الجنين الفقري وجهازه العصبي من عيوب خطيرة تتكوّن في أسابيع الحمل الأولى، لذلك يُوصى به قبل الحمل وفي أشهره الأولى، وطبيبك يحدّده. الحديد يرتفع الطلب عليه لأن دم الأمّ يزداد حجمه ويصنع الجنين دمه، ونقصه يسبّب فقر دم وتعباً. الكالسيوم وفيتامين د لعظام الجنين وأسنانه. واليود لنموّ دماغه وغدّته الدرقية. أمّا تجنّب بعض الأطعمة فسببه أنها قد تحمل جراثيم أو طفيليات تعبر المشيمة وتؤذي الجنين، مثل اللحوم والأسماك النيّئة والألبان غير المبسترة والأجبان الطريّة.',
    en: 'The baby builds its entire body from its mother food through the placenta, so her need for certain elements rises more than her need for extra calories. Folic acid protects the baby spine and nervous system from serious defects that form in the earliest weeks, which is why it is advised before pregnancy and in its early months, and your doctor decides it. The demand for iron rises because the mother blood grows in volume and the baby makes its own blood, and its lack causes anaemia and tiredness. Calcium and vitamin D are for the baby bones and teeth, and iodine for its brain and thyroid growth. As for avoiding some foods, it is because they may carry germs or parasites that cross the placenta and harm the baby, such as raw meat and fish, unpasteurised dairy and soft cheeses.'
  },
  diagnosis: {
    ar: 'العملي هنا عادات لا تحاليل معقّدة، لكن بعض الفحوص توجّه الغذاء: يُقاس مخزون الحديد في الحمل مرّة أو أكثر لأن نقصه شائع، ويُقاس الوزن في كلّ زيارة لتتبّع زيادة معتدلة. الأساس نمط أكل متوازن: نشويات كاملة، وبروتين من مصادر مطهوّة جيداً، وألبان مبسترة، وخضار وفواكه مغسولة جيداً، ودهون صحّية. الماء بوفرة يقي الإمساك والتهاب المسالك. حمض الفوليك يبدأ مبكّراً، وقد يُوصي الطبيب بمكمّلات أخرى حسب التحاليل والحالة، لا حسب الشائعات. تُقسَّم الوجبات صغيرة ومتكرّرة لتخفيف الغثيان والحرقة. أمّا الأطعمة التي تُتجنَّب فتُعرف قائمتها البسيطة من الطبيب وتُتّبع بلا تهويل: أغلب الطعام آمن، والممنوع قليل ومحدَّد.',
    en: 'What is practical here is habits, not complex tests, though some checks guide the diet: iron stores are measured once or more in pregnancy because deficiency is common, and weight is measured at each visit to track moderate gain. The basis is a balanced eating pattern: whole starches, protein from well-cooked sources, pasteurised dairy, well-washed vegetables and fruit, and healthy fats. Plenty of water guards against constipation and urinary infection. Folic acid starts early, and the doctor may advise other supplements according to tests and circumstances, not to rumours. Meals are divided small and frequent to ease nausea and heartburn. The foods to avoid are learned as a simple list from the doctor and followed without alarm: most food is safe, and the forbidden is small and defined.'
  },
  treatment: {
    ar: 'الغذاء الجيّد في الحمل عادة يومية بسيطة: تنويع الطبق، وعدم تفويت وجبات، وشرب ماء كافٍ، وحركة معتدلة تعين الهضم وتضبط الوزن. تُطهى اللحوم والبيض جيداً، وتُغسل الخضار والفاكهة، وتُتجنّب الألبان غير المبسترة والنيّئات. يُقلَّل الكافيين ويُمتنَع عن الكحول تماماً. من الأخطاء الشائعة الإفراط في الأكل بحجّة الحمل فتزيد المشاكل بلا فائدة للجنين، أو العكس: حمية قاسية خوفاً من الوزن تحرم الجنين، أو تناول مكمّلات وأعشاب بلا استشارة ظنّاً أنها كلّها مفيدة بينما بعضها يضرّ. حمض الفوليك يبقى الأهمّ ويبدأ باكراً. والوحام لأطعمة غريبة عادةً لا يضرّ، لكن اشتهاء غير الطعام كالطين أو الثلج بكثرة قد يشير لنقص حديد يستحقّ الفحص.',
    en: 'Good nutrition in pregnancy is a simple daily habit: varying the plate, not missing meals, drinking enough water, and moderate activity that aids digestion and controls weight. Meat and eggs are well cooked, vegetables and fruit are washed, and unpasteurised dairy and raw foods are avoided. Caffeine is reduced and alcohol avoided entirely. Common mistakes are overeating on the excuse of pregnancy so problems increase with no benefit to the baby, or the opposite: a harsh diet from fear of weight that deprives the baby, or taking supplements and herbs without advice on the assumption that all are useful when some harm. Folic acid remains the most important and starts early. Cravings for odd foods are usually harmless, but a strong craving for non-food such as clay or ice may point to iron deficiency worth checking.'
  },
  seeDoctor: {
    ar: 'خذي موعداً قريباً إذا لم تستطيعي الأكل أو الشرب بسبب غثيان شديد، أو نقص وزنك بدل أن يزيد، أو ظهر تعب شديد وشحوب قد يدلّ على فقر دم. وراجعي إذا كنتِ تشتهين بشدّة أكل غير الطعام كالطين أو الثلج، فقد يكون علامة نقص. وإن كان لديك مرض مزمن كالسكّري أو ارتفاع الضغط أو حساسية غذائية أو كنتِ نباتية تماماً، فاطلبي خطّة غذائية مخصّصة مبكّراً. اطلبي الطوارئ إذا ظهرت أعراض تسمّم غذائي شديد — قيء وإسهال مع حمّى وجفاف — فالجفاف في الحمل يحتاج علاجاً سريعاً. أمّا الأسئلة عن الأطعمة المسموحة والممنوعة فمكانها الموعد العادي؛ لا تعتمدي على المتداوَل، فأغلب المخاوف مبالَغ فيها والقائمة الفعلية قصيرة.',
    en: 'Make an early appointment if you cannot eat or drink because of severe nausea, if you lose weight instead of gaining, or if marked tiredness and pallor appear that may indicate anaemia. See a doctor if you strongly crave eating non-food such as clay or ice, which may be a sign of deficiency. If you have a chronic illness such as diabetes, high blood pressure or a food allergy, or you are strictly vegetarian, ask for a tailored eating plan early. Seek emergency care if signs of severe food poisoning appear — vomiting and diarrhoea with fever and dehydration — since dehydration in pregnancy needs prompt treatment. Questions about allowed and forbidden foods belong at the ordinary appointment; do not rely on hearsay, since most fears are exaggerated and the actual list is short.'
  },
  updated: '2026-09-24'
};

DX_BODY['pregnancy-danger-signs'] = {
  symptoms: {
    ar: 'هذه بطاقة تنبيه لا مرض. أغلب الحمل يمرّ بسلام، لكن على الأمّ أن تحفظ علامات قليلة تعني خطراً لا يحتمل الانتظار. أهمّها: نزيف مهبليّ في أيّ وقت من الحمل. صداع شديد لا يزول مع رؤية مشوّشة أو ومضات ضوئية أو ألم أعلى البطن تحت الأضلاع — علامات ارتفاع ضغط الحمل. تورّم مفاجئ في الوجه واليدين. توقّف حركة الجنين أو نقصها الواضح بعد أن انتظمت. نزول ماء أو انقباضات منتظمة مؤلمة قبل الأسبوع السابع والثلاثين. حمّى عالية أو قشعريرة. ألم بطن حادّ مستمرّ. قيء يمنع أيّ أكل أو شرب. صعوبة تنفّس مفاجئة أو ألم صدر. تشوّش وعي أو تشنّج. معرفة هذه القائمة لا تخيف بل تُطمئن، لأنها تحوّل القلق العامّ إلى تصرّف واضح.',
    en: 'This is an alert card, not a disease. Most pregnancies pass safely, but a mother should keep in mind a few signs that mean danger which cannot wait. The most important: vaginal bleeding at any time in pregnancy. A severe headache that does not lift with blurred vision, flashing lights, or upper abdominal pain under the ribs — signs of raised pregnancy blood pressure. Sudden swelling of the face and hands. The baby movement stopping or clearly lessening after it had become regular. Waters breaking or regular painful contractions before the thirty-seventh week. High fever or chills. Persistent sharp abdominal pain. Vomiting that prevents any eating or drinking. Sudden difficulty breathing or chest pain. Confusion or a fit. Knowing this list does not frighten but reassures, because it turns general worry into a clear action.'
  },
  cause: {
    ar: 'كلّ علامة في القائمة نافذةٌ على خطر مختلف. النزيف قد يكون من مشيمة منزاحة أو منفصلة، وكلاهما يهدّد دم الأمّ وأكسجين الجنين. الصداع مع الرؤية وألم أعلى البطن علامات تسمّم الحمل، وهو ارتفاع ضغط يؤذي الكبد والكلى والدماغ وقد ينتهي بتشنّج خطير. توقّف حركة الجنين قد يعني نقص أكسجين يصله عبر مشيمة متعبة. نزول الماء والانقباضات مبكّراً يعني مخاضاً قبل نضج الرئتين. الحمّى قد تدلّ على عدوى تعبر للجنين. صعوبة التنفّس وألم الصدر قد يشيران إلى جلطة، والحمل يزيد ميل الدم للتخثّر. فهم أنّ لكلّ علامة سبباً جدّياً يوضّح لماذا لا تُؤجَّل: النافذة الزمنية فيها قصيرة، والتصرّف السريع يغيّر المصير للأمّ والجنين معاً.',
    en: 'Each sign in the list is a window onto a different danger. Bleeding may be from a low-lying or separating placenta, both threatening the mother blood and the baby oxygen. Headache with visual changes and upper abdominal pain are signs of pre-eclampsia, a rise in blood pressure that harms the liver, kidneys and brain and may end in a dangerous fit. The baby movement stopping may mean reduced oxygen reaching it through a tiring placenta. Waters breaking and contractions early mean labour before the lungs are mature. Fever may indicate an infection crossing to the baby. Difficulty breathing and chest pain may point to a clot, since pregnancy increases the blood tendency to clot. Understanding that each sign has a serious cause makes clear why it is not delayed: the time window is short, and quick action changes the outcome for mother and baby together.'
  },
  diagnosis: {
    ar: 'العملي هنا قاعدة واحدة: عند أيّ من هذه العلامات، اتّصلي بالطوارئ أو توجّهي للمستشفى فوراً ولا تنتظري الموعد ولا الصباح. لا تحاولي التشخيص بنفسك ولا الاطمئنان بمعلومة من الإنترنت. في المستشفى تُقاس علاماتك الحيوية وضغطك، ويُفحص البول للبروتين، ويُسمَع نبض الجنين ويُسجَّل نمطه، وتُجرى موجات صوتية عند الحاجة، وتُطلب تحاليل دم حسب الشكوى. كثير من هذه الزيارات ينتهي بطمأنة، وهذا مكسب لا إزعاج: الفحص السريع يستبعد الخطر أو يمسكه باكراً. احفظي رقم المستشفى وطريقه، وأخبري من معك بخطّة الطوارئ. من المفيد أن تعرفي فصيلة دمك وملخّص حملك لتقوليه بسرعة عند الوصول.',
    en: 'What is practical here is one rule: at any of these signs, call emergency services or go to hospital at once, and do not wait for the appointment or for morning. Do not try to diagnose yourself or seek reassurance from information online. In hospital your vital signs and blood pressure are measured, urine is checked for protein, the baby heartbeat is heard and its pattern recorded, an ultrasound is done when needed, and blood tests are requested according to the complaint. Many of these visits end in reassurance, and that is a gain not a nuisance: a quick check rules out the danger or catches it early. Keep the hospital number and route, and tell those with you your emergency plan. It helps to know your blood group and a summary of your pregnancy to state quickly on arrival.'
  },
  treatment: {
    ar: 'لا تُعالَج القائمة، بل يُتصرَّف عندها. القاعدة الذهبية: عند الشكّ، اذهبي واطمئنّي، فالانتظار هو الخطأ الوحيد الذي لا يُصلَح. من الأخطاء الشائعة القاتلة: تأجيل النزيف أملاً أن يتوقّف، تفسير الصداع الشديد بالإرهاق وتناول مسكّن والنوم، انتظار عودة حركة الجنين إلى الصباح، والخجل من «إزعاج» المستشفى بزيارة قد تكون إنذاراً كاذباً. لا شيء من ذلك يستحقّ المخاطرة. جهّزي مبكّراً: احفظي الأرقام، اعرفي الطريق، رتّبي من يوصلك ومن يبقى مع أطفالك. وإن كان لديك عامل خطر معروف — ضغط مرتفع أو سكّري أو حمل توأم أو مشيمة منزاحة — فاعرفي علاماتك الخاصة من طبيبك مسبقاً. الاستعداد الهادئ خير من الخوف الدائم.',
    en: 'The list is not treated but acted upon. The golden rule: when in doubt, go and be reassured, since waiting is the one mistake that cannot be undone. Common, sometimes fatal mistakes are: delaying bleeding hoping it stops, explaining a severe headache as tiredness and taking a painkiller and sleeping, waiting for the baby movement to return until morning, and being shy of troubling the hospital with a visit that may be a false alarm. None of that is worth the risk. Prepare early: keep the numbers, know the route, arrange who drives you and who stays with your children. If you have a known risk factor — high blood pressure, diabetes, a twin pregnancy or a low-lying placenta — learn your own signs from your doctor in advance. Calm readiness is better than constant fear.'
  },
  seeDoctor: {
    ar: 'اطلبي الطوارئ أو توجّهي للمستشفى فوراً عند أيّ من هذه: نزيف مهبليّ مهما قلّ؛ صداع شديد مع رؤية مشوّشة أو ومضات أو ألم أعلى البطن؛ تورّم مفاجئ في الوجه واليدين؛ توقّف أو نقص واضح في حركة الجنين؛ نزول ماء أو انقباضات منتظمة مؤلمة قبل الأسبوع السابع والثلاثين؛ حمّى عالية أو قشعريرة؛ ألم بطن حادّ مستمرّ؛ قيء يمنع الأكل والشرب؛ صعوبة تنفّس أو ألم صدر أو تورّم وألم في ساق واحدة؛ تشوّش وعي أو تشنّج. لا تنتظري الصباح ولا الموعد ولا زوال العلامة من نفسها. وإن ترددت بين «موعد أم طوارئ» فاختاري الطوارئ في هذه القائمة تحديداً، فكلّها ممّا تُقاس نافذته بالساعات. الطمأنة بعد فحص سريع ربحٌ دائماً، والتأخير وحده هو الخسارة.',
    en: 'Seek emergency care or go to hospital at once at any of these: vaginal bleeding however little; a severe headache with blurred vision, flashes or upper abdominal pain; sudden swelling of the face and hands; stopping or clear reduction of the baby movement; waters breaking or regular painful contractions before the thirty-seventh week; high fever or chills; persistent sharp abdominal pain; vomiting that prevents eating and drinking; difficulty breathing, chest pain, or swelling and pain in one leg; confusion or a fit. Do not wait for morning, for the appointment, or for the sign to pass on its own. If you hesitate between appointment and emergency, choose emergency for this list specifically, since all of it is measured in hours. Reassurance after a quick check is always a gain, and delay alone is the loss.'
  },
  updated: '2026-09-24'
};

/* ==================== الولادة والنفاس ==================== */

DX_BODY['labor-stages'] = {
  symptoms: {
    ar: 'تبدأ علامات المخاض بشكل يختلف من امرأة لأخرى: انقباضات منتظمة تشتدّ وتتقارب مع الوقت ولا تزول بالراحة، وتختلف عن الانقباضات التجريبية بأنها تزداد قوّة وانتظاماً. قد يسبقها أو يصحبها نزول سدادة مخاطية مشوبة بدم خفيف، أو تدفّق ماء عند انفجار كيس الجنين. مع تقدّم المخاض يقوى الألم وينتقل غالباً من أسفل الظهر إلى البطن. في المرحلة الأولى ينفتح عنق الرحم تدريجياً، وهي الأطول. ثم تأتي رغبة قوية بالدفع مع اكتمال الفتح، فتخرج المولود في المرحلة الثانية. ثم تخرج المشيمة في المرحلة الثالثة بعد الولادة بدقائق. معرفة هذا التسلسل تحوّل الخوف من المجهول إلى ترقّب مفهوم لكلّ مرحلة وما يُنتظَر فيها.',
    en: 'The signs of labour begin differently from one woman to another: regular contractions that intensify and draw closer over time and do not ease with rest, differing from practice contractions in that they grow stronger and more regular. They may be preceded or accompanied by the passing of a mucus plug tinged with light blood, or a gush of water when the baby sac breaks. As labour advances the pain strengthens and often moves from the low back to the belly. In the first stage the cervix opens gradually, and it is the longest. Then a strong urge to push comes as the opening completes, so the baby is delivered in the second stage. Then the placenta is delivered in the third stage, minutes after birth. Knowing this sequence turns fear of the unknown into an understood anticipation of each stage and what to expect in it.'
  },
  cause: {
    ar: 'الولادة عمل منظّم لعضلة الرحم. في المرحلة الأولى تنقبض عضلة الرحم بإيقاع متزايد فتسحب عنق الرحم وتفتحه شيئاً فشيئاً حتى يتّسع تماماً؛ تنقسم هذه المرحلة إلى طور كامن بطيء وطور نشط أسرع. الهرمونات — خاصة الأوكسيتوسين — تقود هذه الانقباضات وتقوّيها. في المرحلة الثانية يكتمل الفتح فتدفع انقباضاتُ الرحم مع دفع الأمّ المولودَ عبر الحوض والمهبل إلى الخارج. في المرحلة الثالثة تنقبض الرحم بعد خروج الطفل فتنفصل المشيمة وتخرج، ثم يستمرّ انقباضها ليغلق الأوعية ويمنع النزيف. كلّ مرحلة لها هدف واضح، وتفاوت مدّتها بين النساء وبين الولادة الأولى واللاحقة أمر طبيعيّ لا يعني خللاً.',
    en: 'Birth is an organised work of the womb muscle. In the first stage the womb muscle contracts with a rising rhythm, drawing up the cervix and opening it bit by bit until it is fully wide; this stage divides into a slow latent phase and a faster active phase. Hormones — especially oxytocin — drive these contractions and strengthen them. In the second stage the opening completes, so the womb contractions with the mother pushing move the baby through the pelvis and vagina to the outside. In the third stage the womb contracts after the baby is out, so the placenta separates and is delivered, then its contraction continues to close the vessels and prevent bleeding. Each stage has a clear purpose, and the variation in its length between women and between a first and a later birth is natural and does not mean a fault.'
  },
  diagnosis: {
    ar: 'العملي: متى تتوجّهين للمستشفى ومتى تنتظرين في البيت. للولادة الأولى، القاعدة الشائعة أن تذهبي حين تصير الانقباضات منتظمة قوية كلّ خمس دقائق تقريباً وتستمرّ كلّ واحدة نحو دقيقة على مدى ساعة. لكن اذهبي فوراً بلا انتظار إذا نزل الماء، أو ظهر نزيف، أو قلّت حركة الجنين، أو اشتدّ الألم فجأة. في المستشفى يُقاس اتّساع عنق الرحم بالفحص، ويُسجَّل نبض الجنين ونمط الانقباضات على جهاز، وتُقاس علاماتك الحيوية. يتابع الفريق تقدّم الفتح ونزول رأس الجنين مرحلةً بعد مرحلة. لا تقلقي إن كان الطور الكامن بطيئاً؛ فبدايات المخاض قد تطول، والفريق يميّز المخاض الحقيقي المتقدّم من الانقباضات الأولى المتردّدة.',
    en: 'What is practical: when to head to hospital and when to wait at home. For a first birth, the common rule is to go when contractions become regular and strong about every five minutes, each lasting around a minute over an hour. But go at once without waiting if the waters break, bleeding appears, the baby movement lessens, or the pain suddenly intensifies. In hospital the opening of the cervix is measured by examination, the baby heartbeat and contraction pattern are recorded on a device, and your vital signs are measured. The team follows the progress of the opening and the descent of the baby head stage by stage. Do not worry if the latent phase is slow; the beginnings of labour may be long, and the team distinguishes true advancing labour from the hesitant first contractions.'
  },
  treatment: {
    ar: 'الولادة تُدار لا تُعالَج، والأمّ شريكة فيها لا متلقّية فقط. في الطور الكامن يفيد البقاء في البيت في راحة ما أمكن، والأكل الخفيف والشرب، والمشي وتغيير الوضعيات، وتقنيات التنفّس والاسترخاء. مع اشتداد الألم تتوفّر وسائل تخفيف متعدّدة يناقشها الفريق، من غير الدوائية إلى تخدير موضعي، والاختيار يخصّ كلّ امرأة. من المفيد وجود مرافق داعم، ووضع خطّة ولادة مرنة تُكتب مسبقاً وتحتمل التغيير. من الأخطاء الشائعة الذهاب للمستشفى مبكّراً جداً في أول انقباضة فيطول الانتظار، أو تأخّره حتى تشتدّ فجأة، أو التمسّك بخطّة صارمة لا تحتمل مفاجآت الولادة. الثقة بالفريق والمرونة يجعلان التجربة أهدأ، ولا عيب في طلب تخفيف الألم.',
    en: 'Birth is managed, not treated, and the mother is a partner in it, not only a recipient. In the latent phase it helps to stay home resting where possible, to eat lightly and drink, to walk and change positions, and to use breathing and relaxation techniques. As the pain strengthens, several relief options are available for the team to discuss, from non-medicinal methods to local anaesthesia, and the choice belongs to each woman. A supportive companion helps, as does a flexible birth plan written in advance that allows for change. Common mistakes are going to hospital far too early at the first contraction so the wait is long, or delaying until it suddenly intensifies, or clinging to a rigid plan that allows no surprises. Trust in the team and flexibility make the experience calmer, and there is no shame in asking for pain relief.'
  },
  seeDoctor: {
    ar: 'توجّهي للمستشفى فوراً — دون انتظار انتظام الانقباضات — إذا نزل الماء بغزارة خاصة إن كان أخضر أو دمويّاً، أو ظهر نزيف، أو قلّت حركة الجنين أو توقّفت، أو جاءك ألم بطن حادّ مستمرّ بين الانقباضات، أو صداع شديد مع اضطراب رؤية. واذهبي حين تصير الانقباضات منتظمة قوية كلّ خمس دقائق تستمرّ كلّ واحدة نحو دقيقة على مدى ساعة، وأبكر من ذلك إن كانت ولادتك ليست الأولى أو المستشفى بعيداً. اطلبي الإسعاف إن شعرت برغبة قويّة بالدفع أو ظهر رأس الطفل قبل الوصول، أو إن كان نزول الحبل السرّي قبل الطفل، فهذه حالات لا تحتمل تأخيراً. وإن تجاوزتِ موعدك بلا مخاض فتابعي حسب ما رتّبه طبيبك، ولا تتركي ما بعد الأربعين بلا مراقبة.',
    en: 'Go to hospital at once — without waiting for contractions to become regular — if the waters break heavily, especially if green or bloody, if bleeding appears, if the baby movement lessens or stops, if persistent sharp abdominal pain comes between contractions, or a severe headache with visual disturbance. Go when contractions become regular and strong every five minutes, each lasting about a minute over an hour, and earlier than that if this is not your first birth or the hospital is far. Call an ambulance if you feel a strong urge to push or the baby head appears before arrival, or if the cord comes down before the baby, since these cannot bear delay. And if you pass your date without labour, attend as your doctor has arranged, and do not leave the post-forty period unmonitored.'
  },
  updated: '2026-09-24'
};

DX_BODY['postpartum-recovery'] = {
  symptoms: {
    ar: 'بعد الولادة يمرّ الجسم بتعافٍ محسوس. ينزل دم النفاس أحمر غزيراً أول الأيام ثم يخفّ ويفتح لونه على مدى أسابيع. تُحسّ انقباضات الرحم وهو يعود لحجمه، خاصة أثناء الرضاعة. يؤلم مكان الغرز إن وُجدت، ويصعب الجلوس أوّلاً. يمتلئ الثديان بالحليب في اليوم الثاني أو الثالث فيثقلان ويؤلمان مؤقّتاً. يشيع التعب وقلّة النوم، وتقلّب المزاج والبكاء بلا سبب واضح في الأيام الأولى وهو ما يُعرف بكآبة النفاس العابرة. قد يظهر تعرّق ليليّ، وصعوبة تبوّل أو إمساك أوّل الأيام. كلّها تغيّرات متوقّعة تتحسّن تدريجياً. ما يستحقّ انتباهاً هو ما يشتدّ بدل أن يخفّ: نزيف يزداد، حمّى، ألم متصاعد، أو حزن عميق لا يزول.',
    en: 'After birth the body goes through a felt recovery. Postpartum bleeding flows red and heavy in the first days then eases and lightens in colour over weeks. Contractions of the womb are felt as it returns to size, especially during breastfeeding. The stitches, if any, hurt and sitting is hard at first. The breasts fill with milk on the second or third day so they grow heavy and ache for a time. Tiredness and little sleep are common, as are mood swings and crying without clear cause in the first days, known as the passing baby blues. Night sweats may appear, with difficulty passing urine or constipation in the early days. These are all expected changes that improve gradually. What deserves attention is what worsens instead of easing: increasing bleeding, fever, rising pain, or a deep sadness that does not lift.'
  },
  cause: {
    ar: 'يعود الجسم من حالة الحمل إلى ما قبله. الرحم الذي كبر كثيراً ينقبض ويصغر خلال أسابيع حتى يعود لحجمه، ودم النفاس هو تصريف بطانته وموضع المشيمة أثناء الالتئام. تهبط هرمونات الحمل هبوطاً حادّاً بعد خروج المشيمة، وهذا الهبوط مع قلّة النوم وإرهاق الولادة سبب تقلّب المزاج وكآبة النفاس العابرة. يرتفع هرمون الحليب فيمتلئ الثديان. تتعافى أنسجة الحوض والعجان من ضغط الولادة، وتعود المثانة والأمعاء لعملها المعتاد بعد بطء مؤقّت. التعرّق الليليّ طريقة الجسم لطرح السوائل الزائدة التي احتبسها في الحمل. كلّ ذلك مسار طبيعيّ يحتاج وقتاً وراحة، لا مرض يُعالَج، لكنّه يجعل جسم الأمّ أكثر عرضة مؤقّتاً للعدوى والتخثّر فتُراقَب علاماتهما.',
    en: 'The body returns from the state of pregnancy to what came before. The womb, which grew greatly, contracts and shrinks over weeks until it returns to size, and the postpartum bleeding is the discharge of its lining and the placental site as they heal. Pregnancy hormones drop sharply after the placenta is delivered, and this drop, with little sleep and the exhaustion of birth, causes the mood swings and passing baby blues. The milk hormone rises so the breasts fill. The pelvic and perineal tissues recover from the pressure of birth, and the bladder and bowel return to their usual work after a temporary slowing. Night sweats are the body way of shedding the extra fluid it held in pregnancy. All this is a natural course needing time and rest, not a disease to treat, but it leaves the mother body temporarily more prone to infection and clotting, so their signs are watched.'
  },
  diagnosis: {
    ar: 'المتابعة بعد الولادة مهمّة وإن شعرت الأمّ أنها بخير. تُتابَع علاماتها الحيوية والنزيف والتئام الغرز، ويُسأل عن التبوّل والتبرّز وامتلاء الثدي. تُجرى زيارة أو أكثر خلال الأسابيع الستة الأولى، يُقيَّم فيها التعافي الجسديّ، وتُفحَص علامات فقر الدم إن كان النزيف كثيراً في الولادة، ويُسأل عن المزاج بصراحة للتفريق بين كآبة النفاس العابرة واكتئاب ما بعد الولادة الذي يحتاج دعماً. يُعطى مجال للسؤال عن الرضاعة ووسائل تنظيم الحمل واستئناف النشاط. تُفحَص علامات التخثّر في الساق والعدوى في الرحم أو الجرح أو الثدي. الفكرة أن كثيراً من مشاكل ما بعد الولادة يُمسَك باكراً بسؤال بسيط، لذا لا يُهمَل موعد المتابعة ولو مرّ التعافي هادئاً.',
    en: 'Follow-up after birth matters even if the mother feels well. Her vital signs, bleeding and the healing of stitches are followed, and she is asked about passing urine and stool and the filling of the breast. One or more visits are made in the first six weeks, assessing physical recovery, checking for signs of anaemia if bleeding was heavy at birth, and asking about mood frankly to separate the passing baby blues from postnatal depression, which needs support. Room is given to ask about breastfeeding, contraception and resuming activity. Signs of clotting in the leg and of infection in the womb, the wound or the breast are checked. The idea is that many after-birth problems are caught early by a simple question, so the follow-up appointment is not neglected even if recovery has passed quietly.'
  },
  treatment: {
    ar: 'التعافي يُدعَم بالراحة قدر ما يسمح المولود، وقبول المساعدة من حولها، والتغذية الجيّدة وشرب الماء خاصة مع الرضاعة، وحركة خفيفة متدرّجة تعين الدورة الدموية وتقي التخثّر. تُعتنى منطقة الغرز بالنظافة والماء الدافئ. تُخفَّف احتقان الثدي بالرضاعة المتكرّرة. من الأخطاء الشائعة أن تُحمّل الأمّ نفسها فوق طاقتها لتثبت أنها «قوية»، وإهمال علامات الاكتئاب على أنها مجرّد تعب، والعودة للمجهود العنيف أو رفع الأثقال باكراً، وكتمان مشاعر الحزن خجلاً. طلب الدعم النفسيّ والعمليّ ليس ضعفاً بل جزء من التعافي. يُؤجَّل الجماع واستئناف النشاط الشاقّ حتى يسمح الطبيب، ويُناقَش تنظيم الحمل مبكّراً لأن الخصوبة قد تعود قبل عودة الدورة.',
    en: 'Recovery is supported by rest as much as the newborn allows, accepting help from those around, good nutrition and drinking water especially with breastfeeding, and gentle graded movement that aids circulation and guards against clotting. The stitches area is cared for with cleanliness and warm water. Breast engorgement is eased by frequent feeding. Common mistakes are the mother overburdening herself to prove she is strong, dismissing signs of depression as mere tiredness, returning to heavy effort or lifting weights early, and hiding feelings of sadness out of shame. Asking for emotional and practical support is not weakness but part of recovery. Intercourse and resuming strenuous activity are postponed until the doctor allows, and contraception is discussed early because fertility may return before the period does.'
  },
  seeDoctor: {
    ar: 'اطلبي الطوارئ فوراً إذا زاد نزيف النفاس فجأة حتى يبلّل أكثر من فوطة في الساعة أو نزلت جلطات كبيرة، أو ارتفعت حرارتك مع قشعريرة، أو ظهر ألم وتورّم واحمرار في ساق واحدة أو ضيق نفس أو ألم صدر — فقد يكون تخثّراً. وكذلك عند صداع شديد مع اضطراب رؤية بعد الولادة، فارتفاع الضغط قد يظهر في النفاس أيضاً. وخذي موعداً قريباً إذا صار دم النفاس كريه الرائحة، أو اشتدّ ألم أسفل البطن، أو احمرّ الثدي وآلمَ مع حمّى، أو تأخّر التئام الغرز أو خرج منها صديد، أو صعُب عليك التبوّل والتحكّم به. وراجعي دون تردّد إذا استمرّ الحزن العميق أو فقدان الاهتمام أكثر من أسبوعين، أو راودتك أفكار تؤذين بها نفسك أو طفلك — فاكتئاب ما بعد الولادة يُعالَج ولا يُحتمَل صامتاً.',
    en: 'Seek emergency care at once if postpartum bleeding suddenly increases so it soaks more than a pad an hour or passes large clots, if your temperature rises with chills, or if pain, swelling and redness appear in one leg, or breathlessness or chest pain — which may be a clot. The same applies to a severe headache with visual disturbance after birth, since raised blood pressure can also appear in the postpartum period. Make an early appointment if the postpartum blood becomes foul-smelling, lower abdominal pain worsens, a breast reddens and aches with fever, the stitches are slow to heal or discharge pus, or passing and controlling urine becomes hard. See a doctor without hesitation if deep sadness or loss of interest lasts more than two weeks, or thoughts of harming yourself or your baby come to you, since postnatal depression is treatable and must not be borne in silence.'
  },
  updated: '2026-09-24'
};

DX_BODY['breastfeeding'] = {
  symptoms: {
    ar: 'ما تعيشه الأمّ في الرضاعة يتغيّر بالأيام. أول ما ينزل هو اللبأ، سائل أصفر غليظ قليل الكمية غنيّ بالمناعة، يكفي معدة المولود الصغيرة. في اليوم الثاني أو الثالث «ينزل الحليب» فيمتلئ الثديان ويثقلان ويسخنان، وقد يؤلمان مؤقّتاً. الرضعة الجيّدة يلتقم فيها الطفل الهالة لا الحلمة وحدها، ويُسمَع بلعه، وتُحسّ الأمّ شدّاً لا ألماً حادّاً. علامات شبع المولود: يهدأ ويترك الثدي راضياً، ويبلّل حفاضات كافية، ويزيد وزنه. أما ما يقلق فهو ألم شديد مستمرّ أو تشقّق نازف في الحلمة، واحتقان قاسٍ لا يخفّ، أو احمرار وحرارة في جزء من الثدي مع حمّى، أو علامات جفاف وقلّة بلل الحفاض عند الطفل. البداية قد تكون متعبة لكنها تتحسّن مع تصحيح الالتقام.',
    en: 'What a mother lives in breastfeeding changes by the day. The first to come is colostrum, a thick yellow fluid, small in amount and rich in immunity, enough for the newborn tiny stomach. On the second or third day the milk comes in, so the breasts fill, grow heavy and warm, and may ache for a time. In a good feed the baby takes the areola, not the nipple alone, its swallowing is heard, and the mother feels a pull, not a sharp pain. Signs the newborn is satisfied: it settles and leaves the breast content, wets enough nappies, and gains weight. What worries is severe persistent pain or a cracked bleeding nipple, hard engorgement that does not ease, redness and heat in part of the breast with fever, or signs of dehydration and few wet nappies in the baby. The start may be tiring but improves as the latch is corrected.'
  },
  cause: {
    ar: 'إنتاج الحليب يقوم على العرض والطلب: كلّما رضع الطفل أو شُفط الحليب أكثر، صنع الثدي أكثر؛ لذلك الرضاعة المتكرّرة الباكرة تبني كمية جيّدة. يقود العملية هرمونان: أحدهما يأمر الثدي بصنع الحليب ويرتفع مع كلّ رضعة، والآخر يطلق الحليب من مخازنه عند بدء الرضاعة وهو ما يُحسّ كوخز أو تدفّق. حليب الأمّ يتغيّر تركيبه مع نموّ الطفل وحتى خلال الرضعة الواحدة ليناسب حاجته، ويحمل أجساماً مناعية تحميه من العدوى في أشهره الأولى، وهذا ما لا يُصنَع في أيّ بديل. صعوبات البداية غالباً سببها التقام خاطئ يجعل الرضاعة مؤلمة وغير فعّالة، أو مباعدة الرضعات فيقلّ التحفيز فيقلّ الحليب — وكلاهما يُصلَح بتصحيح الوضعية وزيادة عدد الرضعات.',
    en: 'Milk production rests on supply and demand: the more the baby feeds or milk is expressed, the more the breast makes; so frequent early feeding builds a good supply. Two hormones lead the process: one orders the breast to make milk and rises with each feed, the other releases milk from its stores at the start of the feed, felt as tingling or flow. Mother milk changes its composition as the baby grows and even within a single feed to suit its need, and carries immune bodies that protect it from infection in its early months, something no substitute makes. Difficulties at the start are usually from a wrong latch that makes feeding painful and ineffective, or spacing the feeds so stimulation falls and milk falls — both corrected by fixing the position and increasing the number of feeds.'
  },
  diagnosis: {
    ar: 'يُتابَع نجاح الرضاعة بعلامات بسيطة أكثر من الأرقام: هل يلتقم الطفل جيداً ويُسمع بلعه، وهل يبلّل حفاضات كافية في اليوم، وهل يزيد وزنه في مواعيد المتابعة بعد نزول أوليّ طبيعيّ في الأيام الأولى. تُوزَن الرضّع دورياً على منحنى نموّ لمتابعة مسارهم لا رقم واحد. إن شكّت الأمّ في قلّة الحليب، فالفحص الحقيقي هو بلل الحفاض وزيادة الوزن لا إحساسها بامتلاء الثدي، فكثير من الأمهات ينتج ما يكفي رغم شعورهنّ أن الثدي «فارغ». عند الألم أو التشقّق يُفحَص التقام الطفل ووضعيته، ويُبحَث عن لسان مربوط يمنع الالتقام. وعند احمرار الثدي مع حمّى يُقيَّم احتمال التهابه. استشارة داعمة مبكّرة تحلّ أغلب المشاكل قبل أن تتفاقم.',
    en: 'The success of breastfeeding is followed by simple signs more than by numbers: does the baby latch well and is its swallowing heard, does it wet enough nappies a day, and does its weight rise at follow-up after a natural initial drop in the first days. Babies are weighed periodically on a growth curve to follow their path, not a single figure. If a mother suspects low milk, the true check is wet nappies and weight gain, not her sense of a full breast, since many mothers make enough although the breast feels empty. With pain or cracking, the baby latch and position are examined and a tongue-tie that prevents latching is looked for. With breast redness and fever, the chance of its inflammation is assessed. Early supportive counselling solves most problems before they worsen.'
  },
  treatment: {
    ar: 'الأساس رضاعة مبكّرة ومتكرّرة عند الطلب، والتقام صحيح يأخذ فيه الطفل الهالة لا الحلمة وحدها، وتناوب الثديين. تُدعَم الأمّ بالراحة والسوائل والغذاء الجيّد وبيئة هادئة وقت الرضعة. للتشقّق: تصحيح الالتقام أوّلاً، وتعريض الحلمة للهواء، ودهنها بقطرة من الحليب نفسه. للاحتقان: رضاعة أكثر وكمّادات دافئة قبلها وباردة بعدها. من الأخطاء الشائعة إعطاء بديل باكراً عند أول صعوبة فيقلّ التحفيز فيقلّ الحليب، ومباعدة الرضعات بمواعيد صارمة، وإيقاف الرضاعة عند التهاب الثدي بينما الاستمرار غالباً جزء من علاجه. لا تُقارن الأمّ نفسها بغيرها، وطلب المساعدة من مختصّة رضاعة مبكّراً يوفّر أسابيع من التعب. وإن تعذّرت الرضاعة لسبب، فالبديل يُعطى بمحبّة بلا شعور بالذنب.',
    en: 'The basis is early frequent feeding on demand, a correct latch in which the baby takes the areola not the nipple alone, and alternating the breasts. The mother is supported by rest, fluids, good food and a calm setting at feed time. For cracking: correct the latch first, air the nipple, and dab it with a drop of the milk itself. For engorgement: feed more, with warm compresses before and cool ones after. Common mistakes are giving a substitute early at the first difficulty so stimulation and milk fall, spacing feeds by a strict schedule, and stopping feeding with breast inflammation when continuing is usually part of its treatment. A mother should not compare herself with others, and asking a lactation specialist for help early saves weeks of tiredness. And if breastfeeding is not possible for a reason, the substitute is given with love and without guilt.'
  },
  seeDoctor: {
    ar: 'اطلبي رعاية عاجلة لطفلك إذا ظهرت عليه علامات عدم كفاية الرضاعة: قلّة واضحة في بلل الحفاض، خمول ونعاس زائد أو صعوبة إيقاظه للرضاعة، جفاف الفم، أو اصفرار يزداد. وراجعي طبيب طفلك إن لم يستعد وزنه الأول في الأسبوعين، أو كان لا يهدأ بعد الرضعات ووزنه لا يزيد. أمّا لكِ: راجعي قريباً إذا استمرّ ألم الحلمة الشديد أو تشقّقها رغم تصحيح الالتقام، أو شككتِ بلسان مربوط عند الطفل. واطلبي رعاية عاجلة إذا احمرّ جزء من ثديك وسخن وآلمَ مع حمّى وقشعريرة، فقد يكون التهاباً يحتاج علاجاً سريعاً. لا تتردّدي في طلب مختصّة رضاعة عند أيّ صعوبة مستمرّة؛ الدعم المبكّر يحمي الرضاعة، والانتظار حتى اليأس هو ما ينهيها غالباً.',
    en: 'Seek urgent care for your baby if signs of insufficient feeding appear: a clear reduction in wet nappies, lethargy and excess sleepiness or difficulty waking it to feed, a dry mouth, or increasing yellowness. See your baby doctor if it has not regained its birth weight by two weeks, or if it does not settle after feeds and its weight does not rise. As for you: see a doctor soon if severe nipple pain or cracking persists despite correcting the latch, or you suspect a tongue-tie in the baby. Seek urgent care if part of your breast reddens, warms and aches with fever and chills, since it may be an inflammation needing prompt treatment. Do not hesitate to ask a lactation specialist at any persistent difficulty; early support protects breastfeeding, and waiting until despair is usually what ends it.'
  },
  updated: '2026-09-24'
};

